package org.apache.commons.math.stat.descriptive;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.SecondMoment;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.rank.Max;
import org.apache.commons.math.stat.descriptive.rank.Min;
import org.apache.commons.math.stat.descriptive.summary.Sum;
import org.apache.commons.math.stat.descriptive.summary.SumOfLogs;
import org.apache.commons.math.stat.descriptive.summary.SumOfSquares;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for SummaryStatistics.toString()
 */
public class SummaryStatistics_toString_TriageGen0Test {

    @Test
    public void testToStringWithValues() {
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(1.0);
        stats.addValue(2.0);
        stats.addValue(3.0);

        String result = stats.toString();

        // Expected values based on input [1, 2, 3]
        // n: 3
        // min: 1.0
        // max: 3.0
        // mean: 2.0
        // geometric mean: (1*2*3)^(1/3) = 1.8171205928321397
        // variance: ((1-2)^2 + (2-2)^2 + (3-2)^2) / (3-1) = 1.0
        // sum of squares: 1^2 + 2^2 + 3^2 = 14.0
        // standard deviation: sqrt(1.0) = 1.0
        // sum of logs: ln(1) + ln(2) + ln(3) = 0 + 0.6931471805599453 + 1.0986122886681096 = 1.791759469228055

        assertTrue("Should contain header", result.contains("SummaryStatistics:"));
        assertTrue("Should contain n", result.contains("n: 3"));
        assertTrue("Should contain min", result.contains("min: 1.0"));
        assertTrue("Should contain max", result.contains("max: 3.0"));
        assertTrue("Should contain mean", result.contains("mean: 2.0"));
        assertTrue("Should contain geometric mean", result.contains("geometric mean: 1.8171205928321397"));
        assertTrue("Should contain variance", result.contains("variance: 1.0"));
        assertTrue("Should contain sum of squares", result.contains("sum of squares: 14.0"));
        assertTrue("Should contain standard deviation", result.contains("standard deviation: 1.0"));
        assertTrue("Should contain sum of logs", result.contains("sum of logs: 1.791759469228055"));
    }

    @Test
    public void testToStringEmpty() {
        SummaryStatistics stats = new SummaryStatistics();
        String result = stats.toString();

        // For empty stats, Commons Math returns NaN for most metrics and 0 for n
        assertTrue(result.contains("n: 0"));
        assertTrue(result.contains("min: NaN"));
        assertTrue(result.contains("max: NaN"));
        assertTrue(result.contains("mean: NaN"));
        assertTrue(result.contains("geometric mean: NaN"));
        assertTrue(result.contains("variance: NaN"));
        assertTrue(result.contains("sum of squares: 0.0"));
        assertTrue(result.contains("standard deviation: NaN"));
        assertTrue(result.contains("sum of logs: 0.0"));
    }

    @Test
    public void testToStringSingleValue() {
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(5.0);
        String result = stats.toString();

        // For n=1, variance and std dev are typically NaN or 0 depending on implementation (Commons Math returns NaN for sample variance when n=1)
        assertTrue(result.contains("n: 1"));
        assertTrue(result.contains("min: 5.0"));
        assertTrue(result.contains("max: 5.0"));
        assertTrue(result.contains("mean: 5.0"));
        assertTrue(result.contains("geometric mean: 5.0"));
        assertTrue(result.contains("variance: NaN"));
        assertTrue(result.contains("sum of squares: 25.0"));
        assertTrue(result.contains("standard deviation: NaN"));
        assertTrue(result.contains("sum of logs: 1.6094379124341003"));
    }

    @Test
    public void testToStringWithNegativeValues() {
        // Note: Geometric mean is typically NaN for sets containing negative numbers
        SummaryStatistics stats = new SummaryStatistics();
        stats.addValue(-1.0);
        stats.addValue(2.0);
        String result = stats.toString();

        assertTrue(result.contains("n: 2"));
        assertTrue(result.contains("min: -1.0"));
        assertTrue(result.contains("max: 2.0"));
        assertTrue(result.contains("geometric mean: NaN"));
    }
}
